

# This file was *autogenerated* from the file /workspace/leanproject/Submission/find_small_counterexample.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_40 = Integer(40); _sage_const_10 = Integer(10); _sage_const_16 = Integer(16); _sage_const_4 = Integer(4); _sage_const_9 = Integer(9); _sage_const_160 = Integer(160); _sage_const_2 = Integer(2); _sage_const_8 = Integer(8); _sage_const_3 = Integer(3); _sage_const_11 = Integer(11); _sage_const_31 = Integer(31); _sage_const_19 = Integer(19); _sage_const_23 = Integer(23); _sage_const_0 = Integer(0); _sage_const_10000 = Integer(10000)
import sys
import time

def precompute_V():
    V = {_sage_const_1 }
    for s in range(_sage_const_40 ):
        fs = (_sage_const_10  * _sage_const_16 **s + _sage_const_16  * _sage_const_4 **s + _sage_const_10 ) // _sage_const_9 
        for i in range(_sage_const_160 ):
            val = fs * _sage_const_4 **i
            V.add(val)
    return sorted(list(V))

all_V = precompute_V()

N_max = _sage_const_2  * _sage_const_10 **_sage_const_8 
limit = N_max * N_max
V_target = [v for v in all_V if v < limit]

# We will use exactly 5 base primes
selected_primes = [_sage_const_3 , _sage_const_11 , _sage_const_31 , _sage_const_19 , _sage_const_23 ]
# Let's find the best residues for these 5 primes on V_target
selected_residues = {}
uncovered = list(V_target)

for p in selected_primes:
    cov_for_r = [_sage_const_0 ] * p
    for v in uncovered:
        v_mod = v % p
        if v_mod == _sage_const_0 :
            cov_for_r[_sage_const_0 ] += _sage_const_1 
        elif pow(v_mod, (p-_sage_const_1 )//_sage_const_2 , p) == _sage_const_1 :
            for r in range(_sage_const_1 , p):
                if (r*r) % p == v_mod:
                    cov_for_r[r] += _sage_const_1 
                    cov_for_r[p-r] += _sage_const_1 
                    break
    max_cov = max(cov_for_r)
    best_r = cov_for_r.index(max_cov)
    selected_residues[p] = best_r
    
    # Remove covered
    new_uncovered = []
    r2 = (best_r * best_r) % p
    for v in uncovered:
        if v % p != r2:
            new_uncovered.append(v)
    uncovered = new_uncovered
    print(f"Prime {p}, residue {best_r} (uncovered remaining: {len(uncovered)})")

moduli = [_sage_const_2 ] + selected_primes
residues = [_sage_const_1 ] + [selected_residues[p] for p in selected_primes]
from math import prod as math_prod
base_prod = math_prod(moduli)
N0 = int(crt(residues, moduli))

print(f"CRT base: N0 = {N0}, prod = {base_prod}")

start_time = time.time()
found = False
for k in range(_sage_const_10000 ):
    N = N0 + k * base_prod
    if N <= _sage_const_1 :
        continue
    if N >= N_max:
        break
        
    N2 = N * N
    V_actual = [v for v in all_V if v < N2]
    
    all_blocked = True
    blocking_primes = {}
    for v in V_actual:
        diff = N2 - v
        found_p = None
        for p in selected_primes:
            if diff % p == _sage_const_0  and diff % (p*p) != _sage_const_0 :
                found_p = p
                break
        if found_p is None:
            factors = factor(diff)
            for p, exp in factors:
                if p % _sage_const_4  == _sage_const_3  and exp % _sage_const_2  != _sage_const_0 :
                    found_p = int(p)
                    break
        if found_p is not None:
            blocking_primes[v] = found_p
        else:
            all_blocked = False
            break
            
    if all_blocked:
        print(f"\nSUCCESS! Found N = {N} (k = {k}) in {time.time() - start_time:.2f}s")
        print(f"N^2 = {N2}")
        print(f"V_all size = {len(V_actual)}")
        print(f"blocking_primes = {blocking_primes}")
        found = True
        
        with open("/workspace/leanproject/Submission/success_sage_found.py", "w") as f:
            f.write(f"N = {N}\n")
            f.write(f"blocking_primes = {blocking_primes}\n")
        break

if not found:
    print(f"No counterexample found up to {N_max}")

